190|static struct siphash *
191|sip24_init(struct siphash *H, const struct sipkey *key) {
192|  H->v0 = SIP_ULL(0x736f6d65U, 0x70736575U) ^ key->k[0];
193|  H->v1 = SIP_ULL(0x646f7261U, 0x6e646f6dU) ^ key->k[1];
194|  H->v2 = SIP_ULL(0x6c796765U, 0x6e657261U) ^ key->k[0];
195|  H->v3 = SIP_ULL(0x74656462U, 0x79746573U) ^ key->k[1];
196|
197|  H->p = H->buf;
198|  H->c = 0;
199|
200|  return H;
201|} /* sip24_init() */

205|static struct siphash *
206|sip24_update(struct siphash *H, const void *src, size_t len) {
207|  const unsigned char *p = (const unsigned char *)src, *pe = p + len;
208|  uint64_t m;
209|
210|  do {
211|    while (p < pe && H->p < sip_endof(H->buf))
212|      *H->p++ = *p++;
213|
214|    if (H->p < sip_endof(H->buf))
215|      break;
216|
217|    m = SIP_U8TO64_LE(H->buf);
218|    H->v3 ^= m;
219|    sip_round(H, 2);
220|    H->v0 ^= m;
221|
222|    H->p = H->buf;
223|    H->c += 8;
224|  } while (p < pe);
225|
226|  return H;
227|} /* sip24_update() */

229|static uint64_t
230|sip24_final(struct siphash *H) {
231|  const char left = (char)(H->p - H->buf);
232|  uint64_t b = (H->c + left) << 56;
233|
234|  switch (left) {
235|  case 7:
236|    b |= (uint64_t)H->buf[6] << 48;
237|    /* fall through */
238|  case 6:
239|    b |= (uint64_t)H->buf[5] << 40;
240|    /* fall through */
241|  case 5:
242|    b |= (uint64_t)H->buf[4] << 32;
243|    /* fall through */
244|  case 4:
245|    b |= (uint64_t)H->buf[3] << 24;
246|    /* fall through */
247|  case 3:
248|    b |= (uint64_t)H->buf[2] << 16;
249|    /* fall through */
250|  case 2:
251|    b |= (uint64_t)H->buf[1] << 8;
252|    /* fall through */
253|  case 1:
254|    b |= (uint64_t)H->buf[0] << 0;
255|    /* fall through */
256|  case 0:
257|    break;
258|  }
259|
260|  H->v3 ^= b;
261|  sip_round(H, 2);
262|  H->v0 ^= b;
263|  H->v2 ^= 0xff;
264|  sip_round(H, 4);
265|
266|  return H->v0 ^ H->v1 ^ H->v2 ^ H->v3;
267|} /* sip24_final() */

