275|/* TAG represents an open element.
276|   The name of the element is stored in both the document and API
277|   encodings.  The memory buffer 'buf' is a separately-allocated
278|   memory area which stores the name.  During the XML_Parse()/
279|   XML_ParseBuffer() when the element is open, the memory for the 'raw'
280|   version of the name (in the document encoding) is shared with the
281|   document buffer.  If the element is open across calls to
282|   XML_Parse()/XML_ParseBuffer(), the buffer is re-allocated to
283|   contain the 'raw' name as well.
284|
285|   A parser reuses these structures, maintaining a list of allocated
286|   TAG objects in a free list.
287|*/
288|typedef struct tag {
289|  struct tag *parent;  /* parent of this element */
290|  const char *rawName; /* tagName in the original encoding */
291|  int rawNameLength;
292|  TAG_NAME name; /* tagName in the API encoding */
293|  union {
294|    char *raw;     /* for byte-level access (rawName storage) */
295|    XML_Char *str; /* for character-level access (converted name) */
296|  } buf;           /* buffer for name components */
297|  char *bufEnd;    /* end of the buffer */
298|  BINDING *bindings;
299|} TAG;
