785|expat_heap_stat(XML_Parser rootParser, char operator, XmlBigCount absDiff,
786|                XmlBigCount newTotal, XmlBigCount peakTotal, int sourceLine) {
787|  // NOTE: This can be +infinity or -nan
788|  const float amplification
