793|          "10") " to " EXPAT_FMT_ULL("10") " (" EXPAT_FMT_ULL("10") " peak), amplification %8.2f (xmlparse.c:%d)\n",
794|      (void *)rootParser, rootParser->m_accounting.countBytesDirect, operator,
795|      absDiff, newTotal, peakTotal, (double)amplification, sourceLine);
