798|static bool
799|expat_heap_increase_tolerable(XML_Parser rootParser, XmlBigCount increase,
800|                              int sourceLine) {
801|  assert(rootParser != NULL);
802|  assert(increase > 0);
803|
804|  XmlBigCount newTotal = 0;
805|  bool tolerable = true;
806|
807|  // Detect integer overflow
808|  if ((XmlBigCount)-1 - rootParser->m_alloc_tracker.bytesAllocated < increase) {
809|    tolerable = false;
810|  } else {
811|    newTotal = rootParser->m_alloc_tracker.bytesAllocated + increase;
812|
813|    if (newTotal >= rootParser->m_alloc_tracker.activationThresholdBytes) {
814|      assert(newTotal > 0);
815|      // NOTE: This can be +infinity when dividing by zero but not -nan
816|      const float amplification
817|          = (float)newTotal / (float)rootParser->m_accounting.countBytesDirect;
818|      if (amplification
819|          > rootParser->m_alloc_tracker.maximumAmplificationFactor) {
820|        tolerable = false;
821|      }
822|    }
823|  }
824|
825|  if (! tolerable && (rootParser->m_alloc_tracker.debugLevel >= 1)) {
826|    expat_heap_stat(rootParser, '+', increase, newTotal, newTotal, sourceLine);
827|  }
828|
829|  return tolerable;
830|}
