832|#  if defined(XML_TESTING)
833|void *
834|#  else
835|static void *
836|#  endif
837|expat_malloc(XML_Parser parser, size_t size, int sourceLine) {
838|  // Detect integer overflow
839|  if (SIZE_MAX - size < sizeof(size_t) + EXPAT_MALLOC_PADDING) {
840|    return NULL;
841|  }
842|
843|  const XML_Parser rootParser = getRootParserOf(parser, NULL);
844|  assert(rootParser->m_parentParser == NULL);
845|
846|  const size_t bytesToAllocate = sizeof(size_t) + EXPAT_MALLOC_PADDING + size;
847|
848|  if ((XmlBigCount)-1 - rootParser->m_alloc_tracker.bytesAllocated
849|      < bytesToAllocate) {
850|    return NULL; // i.e. signal integer overflow as out-of-memory
851|  }
852|
853|  if (! expat_heap_increase_tolerable(rootParser, bytesToAllocate,
854|                                      sourceLine)) {
855|    return NULL; // i.e. signal violation as out-of-memory
856|  }
857|
858|  // Actually allocate
859|  void *const mallocedPtr = parser->m_mem.malloc_fcn(bytesToAllocate);
860|
861|  if (mallocedPtr == NULL) {
862|    return NULL;
863|  }
864|
865|  // Update in-block recorded size
866|  *(size_t *)mallocedPtr = size;
867|
868|  // Update accounting
869|  rootParser->m_alloc_tracker.bytesAllocated += bytesToAllocate;
870|
871|  // Report as needed
872|  if (rootParser->m_alloc_tracker.debugLevel >= 2) {
873|    if (rootParser->m_alloc_tracker.bytesAllocated
874|        > rootParser->m_alloc_tracker.peakBytesAllocated) {
875|      rootParser->m_alloc_tracker.peakBytesAllocated
876|          = rootParser->m_alloc_tracker.bytesAllocated;
877|    }
878|    expat_heap_stat(rootParser, '+', bytesToAllocate,
879|                    rootParser->m_alloc_tracker.bytesAllocated,
880|                    rootParser->m_alloc_tracker.peakBytesAllocated, sourceLine);
881|  }
882|
883|  return (char *)mallocedPtr + sizeof(size_t) + EXPAT_MALLOC_PADDING;
884|}
