891|expat_free(XML_Parser parser, void *ptr, int sourceLine) {
892|  assert(parser != NULL);
893|
894|  if (ptr == NULL) {
895|    return;
896|  }
897|
898|  const XML_Parser rootParser = getRootParserOf(parser, NULL);
899|  assert(rootParser->m_parentParser == NULL);
900|
901|  // Extract size (to the eyes of malloc_fcn/realloc_fcn) and
902|  // the original pointer returned by malloc/realloc
903|  void *const mallocedPtr = (char *)ptr - EXPAT_MALLOC_PADDING - sizeof(size_t);
904|  const size_t bytesAllocated
905|      = sizeof(size_t) + EXPAT_MALLOC_PADDING + *(size_t *)mallocedPtr;
906|
907|  // Update accounting
908|  assert(rootParser->m_alloc_tracker.bytesAllocated >= bytesAllocated);
909|  rootParser->m_alloc_tracker.bytesAllocated -= bytesAllocated;
910|
911|  // Report as needed
912|  if (rootParser->m_alloc_tracker.debugLevel >= 2) {
913|    expat_heap_stat(rootParser, '-', bytesAllocated,
914|                    rootParser->m_alloc_tracker.bytesAllocated,
915|                    rootParser->m_alloc_tracker.peakBytesAllocated, sourceLine);
916|  }
917|
918|  // NOTE: This may be freeing rootParser, so freeing has to come last
919|  parser->m_mem.free_fcn(mallocedPtr);
920|}
