926|#  endif
927|expat_realloc(XML_Parser parser, void *ptr, size_t size, int sourceLine) {
928|  assert(parser != NULL);
929|
930|  if (ptr == NULL) {
931|    return expat_malloc(parser, size, sourceLine);
932|  }
933|
934|  if (size == 0) {
935|    expat_free(parser, ptr, sourceLine);
936|    return NULL;
937|  }
938|
939|  const XML_Parser rootParser = getRootParserOf(parser, NULL);
940|  assert(rootParser->m_parentParser == NULL);
941|
942|  // Extract original size (to the eyes of the caller) and the original
943|  // pointer returned by malloc/realloc
944|  void *mallocedPtr = (char *)ptr - EXPAT_MALLOC_PADDING - sizeof(size_t);
945|  const size_t prevSize = *(size_t *)mallocedPtr;
946|
947|  // Classify upcoming change
948|  const bool isIncrease = (size > prevSize);
949|  const size_t absDiff
950|      = (size > prevSize) ? (size - prevSize) : (prevSize - size);
951|
952|  // Ask for permission from accounting
953|  if (isIncrease) {
954|    if (! expat_heap_increase_tolerable(rootParser, absDiff, sourceLine)) {
955|      return NULL; // i.e. signal violation as out-of-memory
956|    }
957|  }
958|
959|  // NOTE: Integer overflow detection has already been done for us
960|  //       by expat_heap_increase_tolerable(..) above
961|  assert(SIZE_MAX - sizeof(size_t) - EXPAT_MALLOC_PADDING >= size);
962|
963|  // Actually allocate
964|  mallocedPtr = parser->m_mem.realloc_fcn(
965|      mallocedPtr, sizeof(size_t) + EXPAT_MALLOC_PADDING + size);
966|
967|  if (mallocedPtr == NULL) {
968|    return NULL;
969|  }
970|
971|  // Update accounting
972|  if (isIncrease) {
973|    assert((XmlBigCount)-1 - rootParser->m_alloc_tracker.bytesAllocated
974|           >= absDiff);
975|    rootParser->m_alloc_tracker.bytesAllocated += absDiff;
976|  } else { // i.e. decrease
977|    assert(rootParser->m_alloc_tracker.bytesAllocated >= absDiff);
978|    rootParser->m_alloc_tracker.bytesAllocated -= absDiff;
979|  }
980|
981|  // Report as needed
982|  if (rootParser->m_alloc_tracker.debugLevel >= 2) {
983|    if (rootParser->m_alloc_tracker.bytesAllocated
984|        > rootParser->m_alloc_tracker.peakBytesAllocated) {
985|      rootParser->m_alloc_tracker.peakBytesAllocated
986|          = rootParser->m_alloc_tracker.bytesAllocated;
987|    }
988|    expat_heap_stat(rootParser, isIncrease ? '+' : '-', absDiff,
989|                    rootParser->m_alloc_tracker.bytesAllocated,
990|                    rootParser->m_alloc_tracker.peakBytesAllocated, sourceLine);
991|  }
992|
993|  // Update in-block recorded size
994|  *(size_t *)mallocedPtr = size;
995|
996|  return (char *)mallocedPtr + sizeof(size_t) + EXPAT_MALLOC_PADDING;
997|}
