1084|static struct sipkey
1085|generate_hash_secret_salt(void) {
1086|  struct sipkey entropy;
1087|
1088|  /* "Failproof" high quality providers: */
1089|#if defined(HAVE_ARC4RANDOM_BUF)
1090|  arc4random_buf(&entropy, sizeof(entropy));
1091|  return ENTROPY_DEBUG("arc4random_buf", entropy);
1092|#elif defined(HAVE_ARC4RANDOM)
1093|  writeRandomBytes_arc4random(&entropy, sizeof(entropy));
1094|  return ENTROPY_DEBUG("arc4random", entropy);
1095|#else
1096|  /* Try high quality providers first .. */
1097|#  ifdef _WIN32
1098|  if (writeRandomBytes_rand_s(&entropy, sizeof(entropy))) {
1099|    return ENTROPY_DEBUG("rand_s", entropy);
1100|  }
1101|#  elif defined(HAVE_GETENTROPY)
1102|  if (writeRandomBytes_getentropy(&entropy, sizeof(entropy))) {
1103|    return ENTROPY_DEBUG("getentropy", entropy);
1104|  }
1105|  errno = 0;
1106|#  elif defined(HAVE_GETRANDOM) || defined(HAVE_SYSCALL_GETRANDOM)
1107|  if (writeRandomBytes_getrandom_nonblock(&entropy, sizeof(entropy))) {
1108|    return ENTROPY_DEBUG("getrandom", entropy);
1109|  }
1110|#  endif
1111|#  if ! defined(_WIN32) && defined(XML_DEV_URANDOM)
1112|  if (writeRandomBytes_dev_urandom(&entropy, sizeof(entropy))) {
1113|    return ENTROPY_DEBUG("/dev/urandom", entropy);
1114|  }
1115|#  endif /* ! defined(_WIN32) && defined(XML_DEV_URANDOM) */
1116|  /* .. and self-made low quality for backup: */
1117|
1118|  entropy.k[0] = 0;
1119|  entropy.k[1] = gather_time_entropy();
1120|#  if ! defined(__wasi__)
1121|  /* Process ID is 0 bits entropy if attacker has local access */
1122|  entropy.k[1] ^= getpid();
1123|#  endif
1124|
1125|  /* Factors are 2^31-1 and 2^61-1 (Mersenne primes M31 and M61) */
1126|  if (sizeof(unsigned long) == 4) {
1127|    entropy.k[1] *= 2147483647;
1128|    return ENTROPY_DEBUG("fallback(4)", entropy);
1129|  } else {
1130|    entropy.k[1] *= 2305843009213693951ULL;
1131|    return ENTROPY_DEBUG("fallback(8)", entropy);
1132|  }
1133|#endif
