1136|static enum XML_Error
1137|callProcessor(XML_Parser parser, const char *start, const char *end,
1138|              const char **endPtr) {
1139|  const size_t have_now = EXPAT_SAFE_PTR_DIFF(end, start);
1140|
1141|  if (parser->m_reparseDeferralEnabled
1142|      && ! parser->m_parsingStatus.finalBuffer) {
1143|    // Heuristic: don't try to parse a partial token again until the amount of
1144|    // available data has increased significantly.
1145|    const size_t had_before = parser->m_partialTokenBytesBefore;
1146|    // ...but *do* try anyway if we're close to causing a reallocation.
1147|    size_t available_buffer
1148|        = EXPAT_SAFE_PTR_DIFF(parser->m_bufferPtr, parser->m_buffer);
1149|#if XML_CONTEXT_BYTES > 0
1150|    available_buffer -= EXPAT_MIN(available_buffer, XML_CONTEXT_BYTES);
1151|#endif
1152|    available_buffer
1153|        += EXPAT_SAFE_PTR_DIFF(parser->m_bufferLim, parser->m_bufferEnd);
1154|    // m_lastBufferRequestSize is never assigned a value < 0, so the cast is ok
1155|    const bool enough
1156|        = (have_now >= 2 * had_before)
1157|          || ((size_t)parser->m_lastBufferRequestSize > available_buffer);
1158|
1159|    if (! enough) {
1160|      *endPtr = start; // callers may expect this to be set
1161|      return XML_ERROR_NONE;
1162|    }
1163|  }
1164|#if defined(XML_TESTING)
1165|  g_bytesScanned += (unsigned)have_now;
1166|#endif
1167|  // Run in a loop to eliminate dangerous recursion depths
1168|  enum XML_Error ret;
1169|  *endPtr = start;
1170|  while (1) {
1171|    // Use endPtr as the new start in each iteration, since it will
1172|    // be set to the next start point by m_processor.
1173|    ret = parser->m_processor(parser, *endPtr, end, endPtr);
1174|
1175|    // Make parsing status (and in particular XML_SUSPENDED) take
1176|    // precedence over re-enter flag when they disagree
1177|    if (parser->m_parsingStatus.parsing != XML_PARSING) {
1178|      parser->m_reenter = XML_FALSE;
1179|    }
1180|
1181|    if (! parser->m_reenter) {
1182|      break;
1183|    }
1184|
1185|    parser->m_reenter = XML_FALSE;
1186|    if (ret != XML_ERROR_NONE)
1187|      return ret;
1188|  }
1189|
1190|  if (ret == XML_ERROR_NONE) {
1191|    // if we consumed nothing, remember what we had on this parse attempt.
1192|    if (*endPtr == start) {
1193|      parser->m_partialTokenBytesBefore = have_now;
1194|    } else {
1195|      parser->m_partialTokenBytesBefore = 0;
1196|    }
1197|  }
1198|  return ret;
