3046|/* Initially tag->rawName always points into the parse buffer;
3047|   for those TAG instances opened while the current parse buffer was
3048|   processed, and not yet closed, we need to store tag->rawName in a more
3049|   permanent location, since the parse buffer is about to be discarded.
3050|*/
3051|static XML_Bool
3052|storeRawNames(XML_Parser parser) {
3053|  TAG *tag = parser->m_tagStack;
3054|  while (tag) {
3055|    size_t bufSize;
3056|    size_t nameLen = sizeof(XML_Char) * (tag->name.strLen + 1);
3057|    size_t rawNameLen;
3058|    char *rawNameBuf = tag->buf.raw + nameLen;
3059|    /* Stop if already stored.  Since m_tagStack is a stack, we can stop
3060|       at the first entry that has already been copied; everything
3061|       below it in the stack is already been accounted for in a
3062|       previous call to this function.
3063|    */
3064|    if (tag->rawName == rawNameBuf)
3065|      break;
3066|    /* For reuse purposes we need to ensure that the
3067|       size of tag->buf is a multiple of sizeof(XML_Char).
3068|    */
3069|    rawNameLen = ROUND_UP(tag->rawNameLength, sizeof(XML_Char));
3070|    /* Detect and prevent integer overflow. */
3071|    if (rawNameLen > (size_t)INT_MAX - nameLen)
3072|      return XML_FALSE;
3073|    bufSize = nameLen + rawNameLen;
3074|    if (bufSize > (size_t)(tag->bufEnd - tag->buf.raw)) {
3075|      char *temp = REALLOC(parser, tag->buf.raw, bufSize);
3076|      if (temp == NULL)
3077|        return XML_FALSE;
3078|      /* if tag->name.str points to tag->buf.str (only when namespace
3079|         processing is off) then we have to update it
3080|      */
3081|      if (tag->name.str == tag->buf.str)
3082|        tag->name.str = (XML_Char *)temp;
3083|      /* if tag->name.localPart is set (when namespace processing is on)
3084|         then update it as well, since it will always point into tag->buf
3085|      */
3086|      if (tag->name.localPart)
3087|        tag->name.localPart
3088|            = (XML_Char *)temp + (tag->name.localPart - tag->buf.str);
3089|      tag->buf.raw = temp;
3090|      tag->bufEnd = temp + bufSize;
3091|      rawNameBuf = temp + nameLen;
3092|    }
3093|    memcpy(rawNameBuf, tag->rawName, tag->rawNameLength);
3094|    tag->rawName = rawNameBuf;
3095|    tag = tag->parent;
3096|  }
3097|  return XML_TRUE;
3098|}
