3124|static enum XML_Error PTRCALL
3125|externalEntityInitProcessor2(XML_Parser parser, const char *start,
3126|                             const char *end, const char **endPtr) {
3127|  const char *next = start; /* XmlContentTok doesn't always set the last arg */
3128|  int tok = XmlContentTok(parser->m_encoding, start, end, &next);
3129|  switch (tok) {
3130|  case XML_TOK_BOM:
3131|#if XML_GE == 1
3132|    if (! accountingDiffTolerated(parser, tok, start, next, __LINE__,
3133|                                  XML_ACCOUNT_DIRECT)) {
3134|      accountingOnAbort(parser);
3135|      return XML_ERROR_AMPLIFICATION_LIMIT_BREACH;
3136|    }
3137|#endif /* XML_GE == 1 */
3138|
3139|    /* If we are at the end of the buffer, this would cause the next stage,
3140|       i.e. externalEntityInitProcessor3, to pass control directly to
3141|       doContent (by detecting XML_TOK_NONE) without processing any xml text
3142|       declaration - causing the error XML_ERROR_MISPLACED_XML_PI in doContent.
3143|    */
3144|    if (next == end && ! parser->m_parsingStatus.finalBuffer) {
3145|      *endPtr = next;
3146|      return XML_ERROR_NONE;
3147|    }
3148|    start = next;
3149|    break;
3150|  case XML_TOK_PARTIAL:
3151|    if (! parser->m_parsingStatus.finalBuffer) {
3152|      *endPtr = start;
3153|      return XML_ERROR_NONE;
3154|    }
3155|    parser->m_eventPtr = start;
3156|    return XML_ERROR_UNCLOSED_TOKEN;
3157|  case XML_TOK_PARTIAL_CHAR:
3158|    if (! parser->m_parsingStatus.finalBuffer) {
3159|      *endPtr = start;
3160|      return XML_ERROR_NONE;
3161|    }
3162|    parser->m_eventPtr = start;
3163|    return XML_ERROR_PARTIAL_CHAR;
3164|  }
3165|  parser->m_processor = externalEntityInitProcessor3;
3166|  return externalEntityInitProcessor3(parser, start, end, endPtr);
