3169|static enum XML_Error PTRCALL
3170|externalEntityInitProcessor3(XML_Parser parser, const char *start,
3171|                             const char *end, const char **endPtr) {
3172|  int tok;
3173|  const char *next = start; /* XmlContentTok doesn't always set the last arg */
3174|  parser->m_eventPtr = start;
3175|  tok = XmlContentTok(parser->m_encoding, start, end, &next);
3176|  /* Note: These bytes are accounted later in:
3177|           - processXmlDecl
3178|           - externalEntityContentProcessor
3179|  */
3180|  parser->m_eventEndPtr = next;
3181|
3182|  switch (tok) {
3183|  case XML_TOK_XML_DECL: {
