6219|    switch (tok) {
6220|    /* report partial linebreak - it might be the last token */
6221|    case -XML_TOK_PROLOG_S:
6222|      if (parser->m_defaultHandler) {
6223|        reportDefault(parser, parser->m_encoding, s, next);
