6225|          return XML_ERROR_ABORTED;
6226|      }
6227|      *nextPtr = next;
6228|      return XML_ERROR_NONE;
6229|    case XML_TOK_NONE:
6230|      *nextPtr = s;
6231|      return XML_ERROR_NONE;
6232|    case XML_TOK_PROLOG_S:
6233|      if (parser->m_defaultHandler)
6234|        reportDefault(parser, parser->m_encoding, s, next);
6235|      break;
6236|    case XML_TOK_PI:
6237|      if (! reportProcessingInstruction(parser, parser->m_encoding, s, next))
6238|        return XML_ERROR_NO_MEMORY;
6239|      break;
6240|    case XML_TOK_COMMENT:
6241|      if (! reportComment(parser, parser->m_encoding, s, next))
6242|        return XML_ERROR_NO_MEMORY;
6243|      break;
