6349|  const char *textStart, *textEnd;
6350|  const char *next;
6351|  enum XML_Error result;
6352|  OPEN_INTERNAL_ENTITY *openEntity = parser->m_openInternalEntities;
6353|  if (! openEntity)
6354|    return XML_ERROR_UNEXPECTED_STATE;
