6356|  entity = openEntity->entity;
6357|
6358|  // This will return early
6359|  if (entity->hasMore) {
6360|    textStart = ((const char *)entity->textPtr) + entity->processed;
6361|    textEnd = (const char *)(entity->textPtr + entity->textLen);
6362|    /* Set a safe default value in case 'next' does not get set */
6363|    next = textStart;
6364|
6365|    if (entity->is_param) {
