6367|          = XmlPrologTok(parser->m_internalEncoding, textStart, textEnd, &next);
6368|      result = doProlog(parser, parser->m_internalEncoding, textStart, textEnd,
6369|                        tok, next, &next, XML_FALSE, XML_FALSE,
6370|                        XML_ACCOUNT_ENTITY_EXPANSION);
