8183|static int FASTCALL
8184|nextScaffoldPart(XML_Parser parser) {
8185|  DTD *const dtd = parser->m_dtd; /* save one level of indirection */
8186|  CONTENT_SCAFFOLD *me;
8187|  int next;
8188|
8189|  if (! dtd->scaffIndex) {
8190|    /* Detect and prevent integer overflow.
8191|     * The preprocessor guard addresses the "always false" warning
8192|     * from -Wtype-limits on platforms where
8193|     * sizeof(unsigned int) < sizeof(size_t), e.g. on x86_64. */
8194|#if UINT_MAX >= SIZE_MAX
8195|    if (parser->m_groupSize > SIZE_MAX / sizeof(int)) {
8196|      return -1;
8197|    }
8198|#endif
8199|    dtd->scaffIndex = MALLOC(parser, parser->m_groupSize * sizeof(int));
8200|    if (! dtd->scaffIndex)
8201|      return -1;
8202|    dtd->scaffIndex[0] = 0;
8203|  }
8204|
8205|  // Will casting to int be safe further down?
8206|  if (dtd->scaffCount > INT_MAX) {
8207|    return -1;
8208|  }
8209|
8210|  if (dtd->scaffCount >= dtd->scaffSize) {
8211|    CONTENT_SCAFFOLD *temp;
8212|    if (dtd->scaffold) {
8213|      /* Detect and prevent integer overflow */
8214|      if (dtd->scaffSize > UINT_MAX / 2u) {
8215|        return -1;
8216|      }
8217|      /* Detect and prevent integer overflow.
8218|       * The preprocessor guard addresses the "always false" warning
8219|       * from -Wtype-limits on platforms where
8220|       * sizeof(unsigned int) < sizeof(size_t), e.g. on x86_64. */
8221|#if UINT_MAX >= SIZE_MAX
8222|      if (dtd->scaffSize > SIZE_MAX / 2u / sizeof(CONTENT_SCAFFOLD)) {
8223|        return -1;
8224|      }
8225|#endif
8226|
8227|      temp = REALLOC(parser, dtd->scaffold,
8228|                     dtd->scaffSize * 2 * sizeof(CONTENT_SCAFFOLD));
8229|      if (temp == NULL)
8230|        return -1;
8231|      dtd->scaffSize *= 2;
8232|    } else {
8233|      temp = MALLOC(parser, INIT_SCAFFOLD_ELEMENTS * sizeof(CONTENT_SCAFFOLD));
8234|      if (temp == NULL)
8235|        return -1;
8236|      dtd->scaffSize = INIT_SCAFFOLD_ELEMENTS;
8237|    }
8238|    dtd->scaffold = temp;
8239|  }
8240|  next = (int)dtd->scaffCount++;
8241|  me = &dtd->scaffold[next];
8242|  if (dtd->scaffLevel) {
8243|    CONTENT_SCAFFOLD *parent
8244|        = &dtd->scaffold[dtd->scaffIndex[dtd->scaffLevel - 1]];
8245|    if (parent->lastchild) {
8246|      dtd->scaffold[parent->lastchild].nextsib = next;
8247|    }
8248|    if (! parent->childcnt)
8249|      parent->firstchild = next;
8250|    parent->lastchild = next;
8251|    parent->childcnt++;
8252|  }
8253|  me->firstchild = me->lastchild = me->childcnt = me->nextsib = 0;
8254|  return next;
