8257|static XML_Content *
8258|build_model(XML_Parser parser) {
8259|  /* Function build_model transforms the existing parser->m_dtd->scaffold
8260|   * array of CONTENT_SCAFFOLD tree nodes into a new array of
8261|   * XML_Content tree nodes followed by a gapless list of zero-terminated
8262|   * strings. */
8263|  DTD *const dtd = parser->m_dtd; /* save one level of indirection */
8264|  XML_Content *ret;
8265|  XML_Char *str; /* the current string writing location */
8266|
8267|  /* Detect and prevent integer overflow.
8268|   * The preprocessor guard addresses the "always false" warning
8269|   * from -Wtype-limits on platforms where
8270|   * sizeof(unsigned int) < sizeof(size_t), e.g. on x86_64. */
8271|#if UINT_MAX >= SIZE_MAX
8272|  if (dtd->scaffCount > SIZE_MAX / sizeof(XML_Content)) {
8273|    return NULL;
8274|  }
8275|  if (dtd->contentStringLen > SIZE_MAX / sizeof(XML_Char)) {
8276|    return NULL;
8277|  }
8278|#endif
8279|  if (dtd->scaffCount * sizeof(XML_Content)
8280|      > SIZE_MAX - dtd->contentStringLen * sizeof(XML_Char)) {
8281|    return NULL;
8282|  }
8283|
8284|  const size_t allocsize = (dtd->scaffCount * sizeof(XML_Content)
8285|                            + (dtd->contentStringLen * sizeof(XML_Char)));
8286|
8287|  // NOTE: We are avoiding MALLOC(..) here to so that
8288|  //       applications that are not using XML_FreeContentModel but plain
8289|  //       free(..) or .free_fcn() to free the content model's memory are safe.
8290|  ret = parser->m_mem.malloc_fcn(allocsize);
8291|  if (! ret)
8292|    return NULL;
8293|
8294|  /* What follows is an iterative implementation (of what was previously done
8295|   * recursively in a dedicated function called "build_node".  The old recursive
8296|   * build_node could be forced into stack exhaustion from input as small as a
8297|   * few megabyte, and so that was a security issue.  Hence, a function call
8298|   * stack is avoided now by resolving recursion.)
8299|   *
8300|   * The iterative approach works as follows:
8301|   *
8302|   * - We have two writing pointers, both walking up the result array; one does
8303|   *   the work, the other creates "jobs" for its colleague to do, and leads
8304|   *   the way:
8305|   *
8306|   *   - The faster one, pointer jobDest, always leads and writes "what job
8307|   *     to do" by the other, once they reach that place in the
8308|   *     array: leader "jobDest" stores the source node array index (relative
8309|   *     to array dtd->scaffold) in field "numchildren".
8310|   *
8311|   *   - The slower one, pointer dest, looks at the value stored in the
8312|   *     "numchildren" field (which actually holds a source node array index
8313|   *     at that time) and puts the real data from dtd->scaffold in.
8314|   *
8315|   * - Before the loop starts, jobDest writes source array index 0
8316|   *   (where the root node is located) so that dest will have something to do
8317|   *   when it starts operation.
8318|   *
8319|   * - Whenever nodes with children are encountered, jobDest appends
8320|   *   them as new jobs, in order.  As a result, tree node siblings are
8321|   *   adjacent in the resulting array, for example:
8322|   *
8323|   *     [0] root, has two children
8324|   *       [1] first child of 0, has three children
8325|   *         [3] first child of 1, does not have children
8326|   *         [4] second child of 1, does not have children
8327|   *         [5] third child of 1, does not have children
8328|   *       [2] second child of 0, does not have children
8329|   *
8330|   *   Or (the same data) presented in flat array view:
8331|   *
8332|   *     [0] root, has two children
8333|   *
8334|   *     [1] first child of 0, has three children
8335|   *     [2] second child of 0, does not have children
8336|   *
8337|   *     [3] first child of 1, does not have children
8338|   *     [4] second child of 1, does not have children
8339|   *     [5] third child of 1, does not have children
8340|   *
8341|   * - The algorithm repeats until all target array indices have been processed.
8342|   */
8343|  XML_Content *dest = ret; /* tree node writing location, moves upwards */
8344|  XML_Content *const destLimit = &ret[dtd->scaffCount];
8345|  XML_Content *jobDest = ret; /* next free writing location in target array */
8346|  str = (XML_Char *)&ret[dtd->scaffCount];
8347|
8348|  /* Add the starting job, the root node (index 0) of the source tree  */
8349|  (jobDest++)->numchildren = 0;
8350|
8351|  for (; dest < destLimit; dest++) {
8352|    /* Retrieve source tree array index from job storage */
8353|    const int src_node = (int)dest->numchildren;
8354|
8355|    /* Convert item */
8356|    dest->type = dtd->scaffold[src_node].type;
8357|    dest->quant = dtd->scaffold[src_node].quant;
8358|    if (dest->type == XML_CTYPE_NAME) {
8359|      const XML_Char *src;
8360|      dest->name = str;
8361|      src = dtd->scaffold[src_node].name;
8362|      for (;;) {
8363|        *str++ = *src;
8364|        if (! *src)
8365|          break;
8366|        src++;
8367|      }
8368|      dest->numchildren = 0;
8369|      dest->children = NULL;
8370|    } else {
8371|      unsigned int i;
8372|      int cn;
8373|      dest->name = NULL;
8374|      dest->numchildren = dtd->scaffold[src_node].childcnt;
8375|      dest->children = jobDest;
8376|
8377|      /* Append scaffold indices of children to array */
8378|      for (i = 0, cn = dtd->scaffold[src_node].firstchild;
8379|           i < dest->numchildren; i++, cn = dtd->scaffold[cn].nextsib)
8380|        (jobDest++)->numchildren = (unsigned int)cn;
8381|    }
8382|  }
8383|
8384|  return ret;
8385|}
