8410|static XML_Char *
8411|copyString(const XML_Char *s, XML_Parser parser) {
8412|  size_t charsRequired = 0;
8413|  XML_Char *result;
8414|
8415|  /* First determine how long the string is */
8416|  while (s[charsRequired] != 0) {
8417|    charsRequired++;
8418|  }
8419|  /* Include the terminator */
8420|  charsRequired++;
8421|
8422|  /* Now allocate space for the copy */
8423|  result = MALLOC(parser, charsRequired * sizeof(XML_Char));
8424|  if (result == NULL)
8425|    return NULL;
8426|  /* Copy the original into place */
8427|  memcpy(result, s, charsRequired * sizeof(XML_Char));
8428|  return result;
