8433|static float
8434|accountingGetCurrentAmplification(XML_Parser rootParser) {
8435|  //                                          1.........1.........12 => 22
8436|  const size_t lenOfShortestInclude = sizeof("<!ENTITY a SYSTEM 'b'>") - 1;
8437|  const XmlBigCount countBytesOutput
8438|      = rootParser->m_accounting.countBytesDirect
8439|        + rootParser->m_accounting.countBytesIndirect;
8440|  const float amplificationFactor
8441|      = rootParser->m_accounting.countBytesDirect
8442|            ? ((float)countBytesOutput
8443|               / (float)(rootParser->m_accounting.countBytesDirect))
8444|            : ((float)(lenOfShortestInclude
8445|                       + rootParser->m_accounting.countBytesIndirect)
8446|               / (float)lenOfShortestInclude);
8447|  assert(! rootParser->m_parentParser);
8448|  return amplificationFactor;
