8475|static void
8476|accountingReportDiff(XML_Parser rootParser,
8477|                     unsigned int levelsAwayFromRootParser, const char *before,
8478|                     const char *after, ptrdiff_t bytesMore, int source_line,
8479|                     enum XML_Account account) {
8480|  assert(! rootParser->m_parentParser);
8481|
8482|  fprintf(stderr,
8483|          " (+" EXPAT_FMT_PTRDIFF_T("6") " bytes %s|%u, xmlparse.c:%d) %*s\"",
8484|          bytesMore, (account == XML_ACCOUNT_DIRECT) ? "DIR" : "EXP",
8485|          levelsAwayFromRootParser, source_line, 10, "");
8486|
8487|  const char ellipis[] = "[..]";
8488|  const size_t ellipsisLength = sizeof(ellipis) /* because compile-time */ - 1;
8489|  const unsigned int contextLength = 10;
8490|
8491|  /* Note: Performance is of no concern here */
8492|  const char *walker = before;
8493|  if ((rootParser->m_accounting.debugLevel >= 3u)
8494|      || (after - before)
8495|             <= (ptrdiff_t)(contextLength + ellipsisLength + contextLength)) {
8496|    for (; walker < after; walker++) {
8497|      fprintf(stderr, "%s", unsignedCharToPrintable(walker[0]));
8498|    }
8499|  } else {
8500|    for (; walker < before + contextLength; walker++) {
8501|      fprintf(stderr, "%s", unsignedCharToPrintable(walker[0]));
8502|    }
8503|    fprintf(stderr, ellipis);
8504|    walker = after - contextLength;
8505|    for (; walker < after; walker++) {
8506|      fprintf(stderr, "%s", unsignedCharToPrintable(walker[0]));
8507|    }
8508|  }
8509|  fprintf(stderr, "\"\n");
8510|}
