8512|static XML_Bool
8513|accountingDiffTolerated(XML_Parser originParser, int tok, const char *before,
8514|                        const char *after, int source_line,
8515|                        enum XML_Account account) {
8516|  /* Note: We need to check the token type *first* to be sure that
8517|   *       we can even access variable <after>, safely.
8518|   *       E.g. for XML_TOK_NONE <after> may hold an invalid pointer. */
8519|  switch (tok) {
8520|  case XML_TOK_INVALID:
8521|  case XML_TOK_PARTIAL:
8522|  case XML_TOK_PARTIAL_CHAR:
8523|  case XML_TOK_NONE:
8524|    return XML_TRUE;
8525|  }
8526|
8527|  if (account == XML_ACCOUNT_NONE)
8528|    return XML_TRUE; /* because these bytes have been accounted for, already */
8529|
8530|  unsigned int levelsAwayFromRootParser;
8531|  const XML_Parser rootParser
8532|      = getRootParserOf(originParser, &levelsAwayFromRootParser);
8533|  assert(! rootParser->m_parentParser);
8534|
8535|  const int isDirect
8536|      = (account == XML_ACCOUNT_DIRECT) && (originParser == rootParser);
8537|  const ptrdiff_t bytesMore = after - before;
8538|
8539|  XmlBigCount *const additionTarget
8540|      = isDirect ? &rootParser->m_accounting.countBytesDirect
8541|                 : &rootParser->m_accounting.countBytesIndirect;
8542|
8543|  /* Detect and avoid integer overflow */
8544|  if (*additionTarget > (XmlBigCount)(-1) - (XmlBigCount)bytesMore)
8545|    return XML_FALSE;
8546|  *additionTarget += bytesMore;
8547|
8548|  const XmlBigCount countBytesOutput
8549|      = rootParser->m_accounting.countBytesDirect
8550|        + rootParser->m_accounting.countBytesIndirect;
8551|  const float amplificationFactor
8552|      = accountingGetCurrentAmplification(rootParser);
8553|  const XML_Bool tolerated
8554|      = (countBytesOutput < rootParser->m_accounting.activationThresholdBytes)
8555|        || (amplificationFactor
8556|            <= rootParser->m_accounting.maximumAmplificationFactor);
8557|
8558|  if (rootParser->m_accounting.debugLevel >= 2u) {
8559|    accountingReportStats(rootParser, "");
8560|    accountingReportDiff(rootParser, levelsAwayFromRootParser, before, after,
8561|                         bytesMore, source_line, account);
8562|  }
8563|
8564|  return tolerated;
8565|}
